<template><main class="admin"><header><button class="brand" @click="$router.push('/')">AI 灵码平台 <small>运营控制中心</small></button><nav><button v-for="x in sections" :key="x.key" :class="{on:section===x.key}" @click="selectSection(x.key)">{{x.label}}</button></nav><button class="back" @click="$router.push('/')">项目工作区</button></header><section class="title"><div><p>PLATFORM CONTROL</p><h1>{{sectionTitle}}</h1><span>{{sectionHint}}</span></div><button @click="load">刷新数据</button></section><div v-if="loading" class="loading">正在读取运营数据…</div><template v-else-if="data"><section v-if="section==='dashboard'" class="dashboard"><div class="metrics"><article v-for="x in metrics" :key="x.label"><small>{{x.label}}</small><strong>{{x.value}}</strong><span>{{x.note}}</span></article></div><div class="dashboard-grid"><section><h2>平台健康</h2><div class="health"><article v-for="x in obs?.health||[]" :key="x.name"><b :class="x.status">{{x.status==='healthy'?'正常':'需关注'}}</b><strong>{{x.name}}</strong><small>{{x.detail}}</small></article></div></section><section><h2>当前告警 <em>{{obs?.alerts?.length||0}}</em></h2><p v-if="!obs?.alerts?.length" class="empty">当前没有需要处理的告警。</p><article v-for="x in (obs?.alerts||[]).slice(0,6)" :key="x.event_id" class="alert"><b :class="x.level">{{x.level==='critical'?'异常':'提示'}}</b><div><strong>{{x.title}} · {{x.project_name}}</strong><small>{{x.detail}}</small></div></article></section></div><section class="recent"><h2>最近运行事件 <small>仅展示 12 条，完整链路请在项目管理中查看</small></h2><article v-for="x in (obs?.timeline||[]).slice(0,12)" :key="x.id"><time>{{time(x.created_at)}}</time><b>{{x.stage}}</b><strong>{{x.project_name}}</strong><span>{{x.summary}}</span><em>{{x.status}}</em></article></section></section><section v-else-if="section==='projects'" class="panel"><div class="subnav"><button v-for="x in projectTabs" :key="x.key" :class="{on:projectTab===x.key}" @click="projectTab=x.key">{{x.label}}</button></div><table v-if="projectTab==='projects'"><thead><tr><th>项目</th><th>创建者</th><th>技术类型</th><th>状态</th><th>最近更新</th><th>操作</th></tr></thead><tbody><tr v-for="x in data.projects" :key="x.id"><td><strong>{{x.name}}</strong><small>#{{x.id}}</small></td><td>{{x.owner}}</td><td>{{x.tech_stack}}</td><td><b>{{x.status}}</b></td><td>{{time(x.updated_at)}}</td><td><button @click="openProject(x,'tasks')">任务</button><button @click="openProject(x,'deployments')">发布</button><button @click="openProject(x,'observability')">观测</button></td></tr></tbody></table><div v-else-if="projectTab==='tasks'" class="groups"><article v-for="x in taskGroups" :key="x.id"><header><div><small>项目 #{{x.id}}</small><h3>{{x.name}}</h3><span>{{x.items.length}} 条任务</span></div><button @click="toggle('task',x.id)">{{expandedTask[x.id]?'收起':'查看链路'}}</button></header><div v-if="expandedTask[x.id]" class="items"><div v-for="i in x.items" :key="i.id"><b>{{i.kind}}</b><span>{{i.summary}}</span><em>{{i.status}}</em><button v-if="canRetry(i)" @click="retry(i)">重新执行</button></div></div></article></div><div v-else-if="projectTab==='deployments'" class="groups"><article v-for="x in deploymentGroups" :key="x.id"><header><div><small>项目 #{{x.id}}</small><h3>{{x.name}}</h3><span>{{x.items.length}} 个发布版本</span></div><button @click="toggle('deploy',x.id)">{{expandedDeploy[x.id]?'收起':'管理版本'}}</button></header><div v-if="expandedDeploy[x.id]" class="items"><div v-for="i in x.items" :key="i.id"><b>版本 #{{i.version}}</b><span>{{time(i.created_at)}}</span><em>{{i.is_active?'线上':i.status}}</em><a v-if="i.url" :href="i.url" target="_blank">打开</a></div></div></article></div><div v-else class="project-observe"><select v-model="observedProject"><option v-for="x in data.projects" :key="x.id" :value="x.id">{{x.name}}</option></select><h2>{{observedName}} 的运行链路</h2><p>最多展示最近 20 条事件，不会无限延伸。</p><div class="items"><div v-for="x in projectTimeline" :key="x.id"><b>{{x.stage}}</b><span>{{x.summary}}</span><em>{{x.status}}</em><small>{{time(x.created_at)}}</small></div></div></div></section><section v-else-if="section==='users'" class="panel"><h2>用户管理</h2><table><thead><tr><th>用户</th><th>邮箱</th><th>角色</th><th>生成配额</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="x in data.users" :key="x.id"><td>{{x.username}}</td><td>{{x.email||'—'}}</td><td>{{x.role}}</td><td><input v-model.number="x.quota" type="number" min="0" @change="saveQuota(x)" /></td><td><b>{{x.status}}</b></td><td><button :disabled="x.id===auth.user?.id" @click="toggleUser(x)">{{x.status==='active'?'停用':'启用'}}</button></td></tr></tbody></table></section><section v-else class="panel"><h2>操作管理</h2><table><thead><tr><th>时间</th><th>操作者</th><th>操作</th><th>对象</th><th>详情</th></tr></thead><tbody><tr v-for="x in data.audits" :key="x.id"><td>{{time(x.created_at)}}</td><td>用户 #{{x.actor_id||'系统'}}</td><td>{{x.action}}</td><td>{{x.target_type}} #{{x.target_id}}</td><td>{{detail(x.detail)}}</td></tr></tbody></table></section></template></main></template>
<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {getAdminObservability,getAdminOverview,retryAdminAssetJob,updateAdminUser} from '../api/admin';import {useAuthStore} from '../stores/auth';const auth=useAuthStore();const data=ref<any>();const obs=ref<any>();const loading=ref(false);const section=ref('dashboard');const projectTab=ref('projects');const observedProject=ref<number>();const expandedTask=ref<Record<number,boolean>>({});const expandedDeploy=ref<Record<number,boolean>>({});const sections=[{key:'dashboard',label:'运营大屏'},{key:'projects',label:'项目管理'},{key:'users',label:'用户管理'},{key:'audits',label:'操作管理'}];const projectTabs=[{key:'projects',label:'项目'},{key:'tasks',label:'素材与任务'},{key:'deployments',label:'发布'},{key:'observability',label:'运行观测'}];const sectionTitle=computed(()=>sections.find(x=>x.key===section.value)?.label);const sectionHint=computed(()=>section.value==='dashboard'?'全局健康、告警和有限运行摘要':section.value==='projects'?'项目、素材、发布与单项目运行证据':'运营配置与可追溯记录');const metrics=computed(()=>data.value?[{label:'全部项目',value:data.value.metrics.projects,note:'工作区'},{label:'用户',value:data.value.metrics.users,note:'账户'},{label:'运行任务',value:data.value.metrics.running_tasks,note:'生成、修改、素材'},{label:'线上站点',value:data.value.metrics.online_sites,note:'当前公开发布'}]:[]);function groups(items:any[]){const map=new Map<number,any[]>();items.forEach(i=>map.set(i.project_id,[...(map.get(i.project_id)||[]),i]));return [...map].map(([id,items])=>({id,name:items[0]?.project_name||`项目 #${id}`,items}));}const taskGroups=computed(()=>groups(data.value?.tasks||[]));const deploymentGroups=computed(()=>groups(data.value?.deployments||[]));const observedName=computed(()=>data.value?.projects.find((x:any)=>x.id===observedProject.value)?.name||'请选择项目');const projectTimeline=computed(()=> (obs.value?.timeline||[]).filter((x:any)=>x.project_id===observedProject.value).slice(0,20));function time(x:string){return new Date(x).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}function detail(x:any){return x?Object.entries(x).map(([k,v])=>`${k}: ${v}`).join('；'):'—'}async function load(){loading.value=true;try{[data.value,obs.value]=await Promise.all([getAdminOverview(),getAdminObservability()]);observedProject.value??=data.value.projects[0]?.id}catch{ElMessage.error('无法读取管理数据')}finally{loading.value=false}}function selectSection(x:string){section.value=x;if(x==='dashboard')load()}function openProject(x:any,tab:string){section.value='projects';projectTab.value=tab;observedProject.value=x.id;if(tab==='tasks')expandedTask.value[x.id]=true;if(tab==='deployments')expandedDeploy.value[x.id]=true}function toggle(type:string,id:number){const x=type==='task'?expandedTask:expandedDeploy;x.value[id]=!x.value[id]}function canRetry(x:any){return String(x.id).startsWith('asset-')&&!['pending','running','succeeded'].includes(x.status)}async function retry(x:any){try{await retryAdminAssetJob(Number(String(x.id).replace('asset-','')));ElMessage.success('已重新排队');load()}catch{ElMessage.error('重试失败')}}async function saveQuota(x:any){try{await updateAdminUser(x.id,{quota:Number(x.quota)});ElMessage.success('配额已更新');load()}catch{ElMessage.error('更新失败')}}async function toggleUser(x:any){const status=x.status==='active'?'disabled':'active';try{await ElMessageBox.confirm(`确定${status==='active'?'启用':'停用'}用户 ${x.username} 吗？`);await updateAdminUser(x.id,{status});ElMessage.success('账户状态已更新');load()}catch{}}onMounted(load)</script>
<style scoped>.admin{min-height:100vh;background:#f4f6fa;color:#243552;padding:68px 32px 36px}header{position:fixed;z-index:3;inset:0 0 auto;height:68px;display:flex;align-items:center;gap:34px;padding:0 32px;background:#121e34;color:#eff5ff}.brand{border:0;background:transparent;color:#fff;text-align:left;font-weight:800}.brand small{display:block;color:#92a5c7;font-size:11px}nav{display:flex;align-self:stretch}nav button{border:0;border-bottom:3px solid transparent;padding:0 15px;background:transparent;color:#aab8cf;font-weight:700;cursor:pointer}nav button.on{border-color:#4e80ff;color:#fff}.back,.title button,.panel button,.groups button{border:1px solid #c9d6ec;border-radius:6px;padding:7px 10px;background:#fff;color:#2858b8;font-weight:700;cursor:pointer}.back{margin-left:auto;background:#2861dc;color:#fff;border-color:#2861dc}.title{display:flex;justify-content:space-between;align-items:end;padding:30px 0 22px;border-bottom:1px solid #d9e1ee}.title p{margin:0;color:#3164ca;font:700 11px monospace;letter-spacing:.1em}.title h1{margin:7px 0;font-size:36px}.title span{color:#72809a;font-size:14px}.metrics,.health{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:20px 0}.metrics article,.dashboard-grid>section,.recent,.panel{border:1px solid #dbe3f0;border-radius:8px;background:#fff}.metrics article{padding:18px}.metrics small,.metrics span,article small{display:block;color:#78869e;font-size:12px}.metrics strong{display:block;margin:8px 0;font-size:30px}.dashboard-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.dashboard-grid>section,.recent{padding:18px}.dashboard h2,.panel h2{margin:0 0 14px;font-size:16px}.health{grid-template-columns:repeat(3,1fr);margin:0}.health article{padding:10px;border:1px solid #e4e9f2;border-radius:6px}.health strong{font-size:13px}.alert,.recent article{display:grid;grid-template-columns:75px 1fr;gap:10px;padding:10px 0;border-top:1px solid #edf0f5}.alert strong,.recent strong{font-size:13px}.recent{margin-top:14px}.recent h2 small{font-weight:400;color:#7d899d}.recent article{grid-template-columns:95px 70px 180px 1fr 70px}.recent time,.recent em,.items em{font:11px monospace;color:#7e8ba0;font-style:normal}.panel{margin-top:20px;overflow:hidden}.subnav{display:flex;gap:8px;padding:14px;border-bottom:1px solid #e4e9f2}.subnav button{border:0;background:#eef2f8;color:#62718c}.subnav button.on{background:#dfe8ff;color:#2659c4}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:13px 18px;border-bottom:1px solid #edf0f5;font-size:13px}th{background:#fafbfc;color:#71809a;font-size:11px}td small{font:11px monospace}td button+button{margin-left:8px}input{width:72px;padding:6px;border:1px solid #ccd6e7;border-radius:4px}.groups{display:grid;gap:12px;padding:14px;background:#f8f9fc}.groups article{border:1px solid #dce4f0;border-radius:7px;background:#fff}.groups header{position:static;height:auto;display:flex;justify-content:space-between;padding:14px 16px;background:#fff;color:#243552}.groups h3{margin:3px 0;font-size:15px}.items{border-top:1px solid #e8edf4}.items>div{display:grid;grid-template-columns:90px 1fr 90px 100px;gap:14px;align-items:center;padding:11px 16px;border-bottom:1px solid #edf0f5;font-size:13px}.project-observe{padding:18px}.project-observe select{padding:8px;border:1px solid #cdd7e7;border-radius:5px}.empty{color:#8190a6}b{display:inline-block;padding:3px 6px;border-radius:4px;background:#e9f1ff;color:#3260ba;font:11px monospace}.healthy{background:#e4f6ec;color:#178051}.degraded,.warning{background:#fff4d8;color:#9b6a00}.critical,.failed{background:#feecef;color:#bc4057}@media(max-width:800px){.admin{padding-inline:14px}.metrics,.health,.dashboard-grid{grid-template-columns:1fr}.recent article,.items>div{grid-template-columns:1fr}nav{overflow:auto}.brand{display:none}}</style>
